import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {[number, number, number]} position
 * @property {[number, number, number]} rotation
 * @property {[number, number, number]} scale
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {Array<Object>} [dataBindings]
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url: string) => THREE.Texture }} textureLoader
 * @property {{ emit?: (event: string) => void }} [emit]
 * @property {{ [key: string]: (target: THREE.Object3D, params: any) => void }} primitives
 */

/**
 * Creates a textured thumbnail card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----------------------------------------------------------------------
  // Geometry & Texture
  // ----------------------------------------------------------------------
  // Aspect ratio derived from the atlas region (512 × 320 → 1.6)
  const WIDTH = 1.6;
  const HEIGHT = 1.0;

  const geometry = new PlaneGeometry(WIDTH, HEIGHT);

  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  const material = new MeshBasicNodeMaterial({ map: texture });

  const mesh = new Mesh(geometry, material);
  mesh.name = config.name || 'journal-thumbnail-card';

  // ----------------------------------------------------------------------
  // Transform
  // ----------------------------------------------------------------------
  const [px, py, pz] = config.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.scale ?? [1, 1, 1];

  mesh.position.set(px, py, pz);
  mesh.rotation.set(rx, ry, rz);
  mesh.scale.set(sx, sy, sz);

  // ----------------------------------------------------------------------
  // Interaction Handlers
  // ----------------------------------------------------------------------
  const baseY = mesh.position.y;
  const hoverLift = 0.15; // scene units

  mesh.userData.handlers = {};

  // Hover – rise‑in effect
  mesh.userData.handlers.hover = () => {
    gsap.to(mesh.position, {
      y: baseY + hoverLift,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Hover out – return to base position
  mesh.userData.handlers.hoverOut = () => {
    gsap.to(mesh.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Click – emit navigation event
  mesh.userData.handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  };

  // ----------------------------------------------------------------------
  // Data Bindings (exposed for external systems)
  // ----------------------------------------------------------------------
  mesh.userData.bindings = config.dataBindings ? [...config.dataBindings] : [];

  // ----------------------------------------------------------------------
  // Cinematic Primitives (none in this spec but apply if present)
  // ----------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(mesh, primitive.params);
      }
    }
  }

  // ----------------------------------------------------------------------
  // Cleanup
  // ----------------------------------------------------------------------
  mesh.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    geometry.dispose();
    material.dispose();
    if (texture && texture.dispose) texture.dispose();
  };

  return mesh;
}
